module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter JR = 6'b001000,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

reg [31:0] res;

always @(*) begin
    zero = 1'b0;
    carry = 1'b0;
    negative = 1'b0;
    overflow = 1'b0;
    flag = 1'b0;

    case (aluc)
        ADD: begin
            res = a + b;
            carry = (a[31] & b[31] & ~res[31]) | (~a[31] & res[31] & b[31]);
            negative = res[31];
            overflow = (a[31] == b[31]) & (a[31] != res[31]);
        end
        ADDU: begin
            res = a + b;
            carry = (a[31] & b[31] & ~res[31]) | (~a[31] & res[31] & b[31]);
        end
        SUB: begin
            res = a - b;
            carry = (a[31] & ~b[31] & ~res[31]) | (~a[31] & res[31] & b[31]);
            negative = res[31];
            overflow = (a[31] != b[31]) & (a[31] != res[31]);
        end
        SUBU: begin
            res = a - b;
            carry = (a[31] & ~b[31] & ~res[31]) | (~a[31] & res[31] & b[31]);
        end
        AND: res = a & b;
        OR: res = a | b;
        XOR: res = a ^ b;
        NOR: res = ~(a | b);
        SLT: begin
            res = $signed(a) < $signed(b) ? 32'b1 : 32'b0;
            flag = res[0];
        end
        SLTU: begin
            res = a < b ? 32'b1 : 32'b0;
            flag = res[0];
        end
        SLL: res = {a << b[4:0], {28{1'b0}}};
        SRL: res = {a[27:0], {4{1'b0}}};
        SRA: res = {a[31], a[30:0]};
        SLLV: res = {a << (b & 31), {28{1'b0}}};
        SRLV: res = {a[27:0], {4{1'b0}}};
        SRAV: res = {a[31], a[30:0]};
        default: res = 32'b0;
    endcase

    r = res;
    zero = (res == 32'b0);
end

endmodule
